# Общие JS-хелперы. Вывод чисел без экспоненциальной записи: nf печатает p
# значащих цифр фиксированной записью, sv подбирает приставку единицы.
# Сравнение с порогом — с допуском 1e-9 от модуля порога; fx/sx показывают
# число рядом с порогом с таким числом цифр, чтобы округлённое значение лежало
# по ту же сторону порога, что и точное, и не совпадало с округлённым порогом.
# OPT: необязательное поле — пустое даёт null, нечисловое — NaN.
U_JS = r'''
function gt(a,b){return a>b+Math.abs(b)*1e-9;}
function lt(a,b){return a<b-Math.abs(b)*1e-9;}
function ge(a,b){return a>=b-Math.abs(b)*1e-9;}
function le(a,b){return a<=b+Math.abs(b)*1e-9;}
function nf(x,p){if(!isFinite(x))return 'не определено';p=p||4;if(x===0)return '0';var s=Number(x.toPrecision(p));if(s===0)return '0';
 var t=String(s);if(/e\+/i.test(t)){var ee=s.toExponential(p-1).split('e+');t=ee[0].replace('.','')+new Array(Number(ee[1])-(p-1)+1).join('0');if(s<0&&t.charAt(0)!=='-')t='-'+t;}
 else if(/e/i.test(t)){t=s.toFixed(Math.min(100,Math.max(0,p-1-Math.floor(Math.log10(Math.abs(s))))));}
 if(t.indexOf('.')>=0)t=t.replace(/0+$/,'').replace(/\.$/,'');return t.replace('.',',');}
function pp(x,lim){if(Math.abs(x-lim)<=Math.abs(lim)*1e-9)return 4;for(var p=4;p<=12;p++){var r=Number(x.toPrecision(p));if((x<lim?lt(r,lim):gt(r,lim))&&r!==Number(lim.toPrecision(p)))return p;}return 12;}
function fx(x,lim){return nf(x,pp(x,lim));}
var PRE=[[1e12,'Т'],[1e9,'Г'],[1e6,'М'],[1e3,'к'],[1,''],[1e-3,'м'],[1e-6,'мк'],[1e-9,'н'],[1e-12,'п'],[1e-15,'ф']];
function pi_(x,p){var a=Math.abs(x),i;for(i=0;i<PRE.length-1;i++){if(a>=PRE[i][0]*(1-1e-12))break;}
 if(i>0&&Math.abs(Number((a/PRE[i][0]).toPrecision(p)))>=1000)i--;return i;}
function sv(x,unit,p){p=p||4;if(!isFinite(x))return 'не определено';if(x===0)return '0 '+unit;if(Math.abs(x)<1e-15*(1-1e-12))return 'менее 1 ф'+unit;
 var i=pi_(x,p);return nf(x/PRE[i][0],p)+' '+PRE[i][1]+unit;}
function sx(x,lim,unit){var i=pi_(x,4);var k=PRE[i][0];return fx(x/k,lim/k)+' '+PRE[i][1]+unit;}
function sl(x,lim,unit){var i=pi_(x,4);var k=PRE[i][0];return nf(lim/k,pp(x/k,lim/k))+' '+PRE[i][1]+unit;}
function OPT(id){var el=$(id);if(!el)return null;if(String(el.value).trim()==='')return null;return P(id);}
function pc(fr){var v=fr*100;if(v===0)return '0 %';if(v<1e-4)return 'менее 0,0001 %';return nf(v,4)+' %';}
function dbs(x){return x>0&&x<1e-4?'менее 0,0001 дБ':nf(x,4)+' дБ';}
'''

