js=U_JS + r'''
var C0=299792458,KD=20/Math.LN10*Math.PI/C0;
var AU={m100:0.01,m1:1,ft100:1/30.48},AL={m100:'дБ/100 м',m1:'дБ/м',ft100:'дБ/100 фут'};
function sync(){var t=S('mode')==='two';['f0','a0','tg','er'].forEach(function(i){hideF(i,t);});['f1','a1','f2','a2'].forEach(function(i){hideF(i,!t);});}
function init(){$('mode').addEventListener('change',sync);sync();}
function calc(){
var two=S('mode')==='two',key=S('au'),au=AU[key];
var f=P('f'),L=P('len'),pin=OPT('pin'),tol=OPT('tol'),bud=OPT('bud');
if(isNaN(f)||isNaN(L))return err('Заполните числами рабочую частоту и длину линии.');
if(f<1e6||f>1e11)return err('Рабочая частота — от 1 МГц до 100 ГГц: ниже скин-слой сравним с радиусом проводника, выше возможны высшие типы волн, и модель α = k1·√f + k2·f перестаёт быть применимой.');
if(L<=0||L>1e5)return err('Длина линии — больше 0 и не больше 100000 м.');
if(pin!==null){if(isNaN(pin))return err('Мощность на входе — число. Если она не нужна, оставьте поле пустым.');if(pin<=0||pin>1e9)return err('Мощность на входе — больше 0 и не больше 1000000000 Вт.');}
if(tol!==null){if(isNaN(tol))return err('Разброс — число в процентах. Если он не нужен, оставьте поле пустым.');if(tol<0||tol>=100)return err('Разброс паспортного затухания — от 0 до 100 % (не включая 100).');}
if(bud!==null){if(isNaN(bud))return err('Допустимые потери — число в децибелах. Если их нет, оставьте поле пустым.');if(bud<=0||bud>1e6)return err('Допустимые потери — больше 0 и не больше 1000000 дБ.');}
var k1,k2,tg=null,er=null,ex='',h='';
function chk(a,fq,nm){if(isNaN(fq)||isNaN(a))return nm+': введите частоту и паспортное затухание числами. Паспортное затухание страница не подставляет — оно берётся из паспорта вашего кабеля.';
 if(fq<1e6||fq>1e11)return nm+': частота — от 1 МГц до 100 ГГц.';if(a<=0||a*au>1000)return nm+': паспортное затухание — больше 0 и не больше 1000 дБ/м в пересчёте.';return '';}
if(!two){
 var f0=P('f0'),a0=P('a0'),m=chk(a0,f0,'Опорная точка');if(m)return err(m);
 tg=OPT('tg');er=OPT('er');
 if((tg===null)!==(er===null))return err('Задайте tgδ и εr вместе или оставьте оба поля пустыми: диэлектрический член считается по обоим.');
 if(tg!==null){if(isNaN(tg)||isNaN(er))return err('tgδ и εr — числа. Если их нет в паспорте, оставьте оба поля пустыми.');
  if(tg<=0||tg>0.5)return err('tgδ — больше 0 и не больше 0,5.');if(er<1||er>100)return err('εr диэлектрика — от 1 до 100.');}
 var A0=a0*au;k2=tg===null?0:KD*Math.sqrt(er)*tg;
 var rest=A0-k2*f0;
 if(rest<0){if(-rest>A0*1e-9)return err('Потери в диэлектрике при tgδ = '+nf(tg)+' и εr = '+nf(er)+' на частоте f0 — '+nf(k2*f0*100,4)+' дБ/100 м, больше паспортного затухания '+nf(A0*100,4)+' дБ/100 м. Проверьте tgδ, εr и единицу затухания.');rest=0;}
 k1=rest/Math.sqrt(f0);
 if(f/f0>10||f/f0<0.1)ex='; рабочая частота отличается от опорной более чем в 10 раз — это экстраполяция модели, погрешность заметно больше';
}else{
 var f1=P('f1'),a1=P('a1'),f2=P('f2'),a2=P('a2'),m1=chk(a1,f1,'Точка 1'),m2=chk(a2,f2,'Точка 2');
 if(m1)return err(m1);if(m2)return err(m2);
 if(Math.abs(f2-f1)<1e-3*Math.max(f1,f2))return err('Частоты f1 и f2 различаются меньше чем на 0,1 %: по таким двум точкам коэффициенты k1 и k2 не определяются (система вырождена).');
 var A1=a1*au,A2=a2*au,s1=Math.sqrt(f1),s2=Math.sqrt(f2);
 k2=(A2/s2-A1/s1)/(s2-s1);k1=A1/s1-k2*s1;
 var Amax=Math.max(A1,A2);
 if(k1<0){if(-k1*Math.max(s1,s2)<=1e-9*Amax)k1=0;else return err('Коэффициент потерь в проводниках k1 получился отрицательным ('+nf(k1*1000,4)+' дБ/м на √МГц): паспортные точки не согласуются с моделью k1·√f + k2·f. Отрицательный член недопустим. Проверьте значения и единицы.');}
 if(k2<0){if(-k2*Math.max(f1,f2)<=1e-9*Amax)k2=0;else return err('Коэффициент потерь в диэлектрике k2 получился отрицательным ('+nf(k2*1e6,4)+' дБ/м на МГц): затухание растёт медленнее √f, и модель k1·√f + k2·f к этим точкам неприменима. Отрицательный член недопустим. Проверьте значения и единицы.');}
 if(f<Math.min(f1,f2)*(1-1e-9)||f>Math.max(f1,f2)*(1+1e-9))ex='; рабочая частота вне интервала паспортных частот — это экстраполяция модели, погрешность растёт';
}
var ac=k1*Math.sqrt(f),ad=k2*f,al=ac+ad,A=al*L;
function ef(a){return Math.max(Math.exp(-a*Math.LN10/10),5e-324);}
var eta=ef(A),pdis=-Math.expm1(-A*Math.LN10/10);
if(![ac,ad,al,A].every(isFinite))return err('Значения вне диапазона надёжного расчёта.');
h+=row('Потери в проводниках k1: дБ/м на √МГц',nf(k1*1000,5));
h+=row('Потери в диэлектрике k2: дБ/м на МГц',k2===0?(two?'0':'0 — не выделены, tgδ и εr не заданы'):nf(k2*1e6,5));
h+=row('Затухание на частоте f',nf(al*100,5)+' дБ/100 м'+(key==='m100'?'':' ('+nf(al/au,5)+' '+AL[key]+')'));
h+=row('из него в проводниках / в диэлектрике',nf(ac*100,4)+' / '+nf(ad*100,4)+' дБ/100 м');
h+=row('Потери в линии A = α·L',nf(A,5)+' дБ');
h+=row('КПД линии Pвых / Pвх = 10^(−A/10)',pc(eta));
if(pin!==null){h+=row('Мощность на входе',sv(pin,'Вт'));h+=row('Мощность на выходе',sv(pin*eta,'Вт'));h+=row('Рассеивается в кабеле',sv(pin*pdis,'Вт'));}
var Ahi=tol===null?A:A*(1+tol/100);
if(tol!==null){h+=row('Потери с учётом разброса ±'+nf(tol)+' %','от '+nf(A*(1-tol/100),4)+' до '+nf(Ahi,4)+' дБ');h+=row('КПД с учётом разброса','от '+pc(ef(Ahi))+' до '+pc(ef(A*(1-tol/100))));}
if(bud!==null)h+=row('Допустимые потери в линии',nf(bud,4)+' дБ');
var st,why=[],risk=null;
if(bud!==null){
 if(gt(A,bud))risk='потери в линии '+fx(A,bud)+' дБ больше допустимых '+nf(bud,pp(A,bud))+' дБ уже по паспортному значению';
 else if(tol!==null&&gt(Ahi,bud))risk='по паспортному значению потери '+fx(A,bud)+' дБ не больше допустимых, но с разбросом +'+nf(tol)+' % они достигают '+fx(Ahi,bud)+' дБ — больше допустимых '+nf(bud,pp(Ahi,bud))+' дБ';
}
if(bud===null)why.push('допустимые потери не заданы — вывод о достаточности линии не делается; по введённым данным потери '+nf(A,4)+' дБ');
else if(tol===null&&!risk)why.push('разброс паспортного затухания не задан — по паспортному значению потери '+fx(A,bud)+' дБ не больше допустимых '+nf(bud,pp(A,bud))+' дБ, но запас не оценён');
if(risk)st='Риск: '+risk;
else if(why.length)st='Недостаточно данных: '+why.join('; ');
else st='Оценка: потери '+fx(Ahi,bud)+' дБ'+(tol!==null?' (с разбросом +'+nf(tol)+' %)':'')+' не больше допустимых '+nf(bud,pp(Ahi,bud))+' дБ';
st+=ex;
var n=two?'Коэффициенты найдены по двум паспортным точкам из системы α(f1) = k1·√f1 + k2·f1, α(f2) = k1·√f2 + k2·f2; отрицательный коэффициент не принимается. ':'Диэлектрический член '+(tg===null?'не задан: все потери приняты потерями в проводниках, поэтому выше опорной частоты оценка занижена, а ниже — завышена. ':'k2 = (20/ln 10)·π·√εr·tgδ / c найден из tgδ и εr; остаток паспортного затухания отнесён к проводникам. ');
n+='Модель α = k1·√f + k2·f верна, пока толщина проводника много больше скин-слоя, tgδ почти не зависит от частоты, а КСВ линии близок к 1: при рассогласованной нагрузке потери в линии больше. Реальный кабель отклоняется от модели (оплётка, шаг скрутки, влага, старение), поэтому паспортные точки нужны близко к рабочей частоте. Значения Belden в примере взяты из выдачи поиска и требуют сверки с актуальным паспортом.';
out(h+row('Статус',st)+note(n));
}
''',
about="""<div class="formula">α(f) = k1·√f + k2·f,&nbsp;&nbsp;потери в линии A = α·L дБ,&nbsp;&nbsp;Pвых = Pвх·10<sup>−A/10</sup>,&nbsp;&nbsp;КПД = 10<sup>−A/10</sup><br>Одна точка (α0 на f0): k2 = (20/ln 10)·π·√εr·tgδ / c ≈ 9,102·10<sup>−8</sup>·√εr·tgδ дБ/(м·Гц),&nbsp;&nbsp;k1 = (α0 − k2·f0) / √f0<br>Две точки: k2 = (α2/√f2 − α1/√f1) / (√f2 − √f1),&nbsp;&nbsp;k1 = α1/√f1 − k2·√f1</div>
<p><b>Почему √f и f.</b> У линии с малыми потерями затухание складывается из потерь в проводниках и в диэлектрике: α ≈ R′/(2·Z0) + G′·Z0/2 (Позар, глава 2, раздел о линиях с потерями; текст здесь не использовался, а вывод повторён). Из-за скин-эффекта погонное сопротивление R′ пропорционально √f (скин-слой уменьшается как 1/√f), поэтому первый член растёт как √f. Погонная проводимость диэлектрика G′ = ω·C′·tgδ пропорциональна f, а Z0 от частоты почти не зависит, поэтому второй член растёт как f: α<sub>d</sub> = π·f·√εr·tgδ/c неп/м, или 8,686 · π · f · √εr · tgδ / c дБ/м. В единицах, принятых в паспортах, это 0,09102·√εr·tgδ дБ/м на каждый МГц, или 2,774·√εr·tgδ дБ/100 фут на МГц. Модель с двумя коэффициентами k1 и k2 для кабеля описана и в радиолюбительской заметке PA3FWM (в выдаче видна только формулировка; страницу открыть не удалось).</p>
<p><b>Как работают режимы.</b> «Одна частота»: берётся паспортное затухание α0 на f0. Если заданы tgδ и εr, из них считается диэлектрический член k2, остаток относится к проводникам: k1 = (α0 − k2·f0)/√f0; если диэлектрический член окажется больше паспортного затухания, расчёт отклоняется. Если tgδ и εr не заданы, принимается k2 = 0 — все потери в проводниках, и страница прямо пишет, что выше опорной частоты такая оценка занижена. «Две частоты»: k1 и k2 находятся из линейной системы 2×2; при близких частотах система вырождена, и расчёт отклоняется; отрицательный k1 или k2 означает, что точки не согласуются с моделью (например, перепутаны единицы или кабель сильно отличается от идеального), и расчёт тоже отклоняется. Если точки лежат ровно на законе √f, k2 получается нулём с точностью до округления и принимается равным нулю.</p>
<p><b>Мощность и разброс.</b> Потери A в децибелах переводятся в долю мощности η = 10<sup>−A/10</sup>; в кабеле рассеивается Pвх·(1 − η). Разброс паспортного затухания (допуск, старение, влага, температура) вводится в процентах и даёт интервал потерь. Если задан бюджет потерь, страница сравнивает с ним номинальное значение и значение с разбросом; без бюджета или без разброса вывод «в бюджете» не делается — статус «Недостаточно данных».</p>
<table class="t"><tr><th>Частота, МГц</th><th>Belden 8240 (RG-58), дБ/100 фут</th><th>Belden 8267 (RG-213), дБ/100 фут</th></tr>
<tr><td>10</td><td>1,1</td><td>0,55</td></tr><tr><td>100</td><td>3,8</td><td>1,9</td></tr><tr><td>400</td><td>8,4</td><td>4,1</td></tr><tr><td>1000</td><td>14,5</td><td>8,0</td></tr></table>
<p>Таблица взята из выдачи поиска по паспортам Belden (8240 описан в старых паспортах как RG-58A/U type; у 8267 в версиях паспорта различается значение на 1 МГц), редакцию нужно сверить с актуальным паспортом. Это пример данных, а не значения по умолчанию страницы.</p>
<p><b>Чем отличается от соседних страниц.</b> Здесь вводится затухание из паспорта, а не размеры кабеля: Z0 по размерам даёт <a href="volnovoe-soprotivlenie-linii.html">калькулятор волнового сопротивления линии</a>. Отражение от нагрузки и потери на рассогласование — <a href="ksv-otrazhenie.html">калькулятор КСВ</a>. Перевод потерь в дБ в отношение мощностей — <a href="decibel.html">калькулятор децибел</a>, а фиксированные ослабления по мощности — <a href="attenyuator.html">калькулятор аттенюатора</a>.</p>""",
example="""<p>Кабель Belden 8240 (RG-58): по выдаче поиска 1,1 дБ/100 фут на 10 МГц и 3,8 дБ/100 фут на 100 МГц (взято из паспорта в выдаче, редакцию сверить). По двум точкам k1 = 0,010925 дБ/м на √МГц и k2 = 0,00015426 дБ/м на МГц (в дБ/100 фут — 0,33298 и 0,0047018). Предсказание для 400 МГц — 8,540 дБ/100 фут против 8,4 в паспорте (на 1,7 % больше), для 1000 МГц — 15,23 против 14,5 (на 5,0 % больше): модель точна там, где точки близки, и расходится при удалении от них.</p>
<p>Кабель Belden 8267 (RG-213) известен одной точкой: 1,9 дБ/100 фут на 100 МГц. Если принять, что все потери — в проводниках (закон √f), оценка на 10 МГц получается 0,6008 дБ/100 фут против 0,55 в паспорте (на 9,2 % больше), а на 1000 МГц — 6,008 против 8,0 (на 24,9 % меньше): без диэлектрического члена выше опорной частоты оценка занижена. С условными tgδ = 0,0003 и εr = 2,25 эти ошибки меньше, но и они остаются заметными при десятикратной экстраполяции.</p>""",
